/* @lc app=leetcode id=1449 lang=kotlin */ class Solution { fun largestNumber(cost: IntArray, target: Int): String = IntArray(target + 1) { -1 }.also { it[0] = 0 }.let { dp -> (1..target).forEach { t -> dp[t] = cost.indices.filter { t >= cost[it] && dp[t - cost[it]] >= 0 }.maxOfOrNull { dp[t - cost[it]] + 1 } ?: -1 }.let { if (dp[target] < 0) "0" else generateSequence(target to 0) { (t, _) -> if (t == 0) null else (8 downTo 0).first { d -> t >= cost[d] && dp[t - cost[d]] == dp[t] - 1 }.let { d -> t - cost[d] to d + 1 } }.drop(1).joinToString("") { it.second.toString() } } } }